import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;
import java.util.regex.Pattern;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final Pattern SAFE_SORT = Pattern.compile("^[a-zA-Z_]+$");

    // Connection pool managed by container
    private DataSource ds;

    @Override
    public void init(ServletConfig config) throws ServletException {
        try {
            javax.naming.InitialContext ctx = new javax.naming.InitialContext();
            ds = (DataSource) ctx.lookup("java:comp/env/jdbc/reportdb");
        } catch (Exception e) {
            throw new ServletException("Failed to initialize datasource", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String customFilter = req.getParameter("filter");

        // Validate sort column against allowlist pattern
        if (sortCol != null && !SAFE_SORT.matcher(sortCol).matches()) {
            resp.sendError(400, "Invalid sort parameter");
            return;
        }

        // Basic null checks
        if (reportType == null || dateFrom == null || dateTo == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        String query = buildQuery(reportType, dateFrom, dateTo, sortCol, customFilter);
        log.info("Executing report query for type: " + reportType);

        try (Connection conn = ds.getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            java.io.PrintWriter out = resp.getWriter();
            out.print("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(", ");
                    out.print("\"" + meta.getColumnName(i) + "\": ");
                    out.print("\"" + escapeJson(rs.getString(i)) + "\"");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildQuery(String type, String from, String to, String sort, String filter) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM reports_").append(sanitizeTableName(type));
        sb.append(" WHERE created_at >= '").append(from).append("'");
        sb.append(" AND created_at <= '").append(to).append("'");

        // Custom filter - allows advanced users to add conditions
        if (filter != null && !filter.isEmpty()) {
            sb.append(" AND ").append(filter);
        }

        if (sort != null) {
            sb.append(" ORDER BY ").append(sort);
        }
        return sb.toString();
    }

    private String sanitizeTableName(String name) {
        return name.replaceAll("[^a-zA-Z0-9_]", "");
    }

    private String escapeJson(String val) {
        if (val == null) return "null";
        return val.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
